 const mins=(t:string)=>{const [h,m]=String(t).split(':').map(Number);return h*60+m};
 const contextualAppointment=()=>{const a=runtime().agenda;const known=knownAgendaEntries();const entries=known.length?known:(state.day===1?[{id:'marine',time:'10:30',title:'Retrouver Marine',place:'Centre-ville',kind:'rendez-vous',with:'Marine'}]:[]);const now=mins(state.time);return entries.find((e:any)=>{if(e.kind!=='rendez-vous'||!/^\d\d:\d\d$/.test(e.time||'')||state.appointmentStates[e.id]==='done')return false;const delta=now-mins(e.time);e._status=delta>30?'missed':delta>0?'late':'soon';return delta>=-15&&delta<=90})};
 const pendingInvitation=()=>state.invitations.find(x=>x.status==='pending');
